let state=load(); let page='dashboard';
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));return x?{...seed,...x}:structuredClone(seed)}catch{return structuredClone(seed)}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function esc(v=''){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function initials(name='User'){return name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function icon(n){const p={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H8v7H4a1 1 0 0 1-1-1z"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',calendar:'<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/>',brief:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18"/>',wallet:'<path d="M20 7V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h16v10a2 2 0 0 1-2 2H5a3 3 0 0 1-3-3V6"/><path d="M16 14h.01"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',doc:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h6"/>',idea:'<path d="M9 18h6M10 22h4M8.2 14.8A6 6 0 1 1 15.8 14.8C15 15.5 15 16.5 15 17H9c0-.5 0-1.5-.8-2.2z"/>',check:'<path d="m5 12 4 4L19 6"/>',chart:'<path d="M3 3v18h18"/><path d="m7 16 3-4 3 2 5-7"/>',settings:'<path d="M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7z"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-1.8 1.8-.06-.06A1.7 1.7 0 0 0 16 18.4a1.7 1.7 0 0 0-1.1 1.6V20h-2.6v-.08a1.7 1.7 0 0 0-1.1-1.6 1.7 1.7 0 0 0-1.94.28l-.06.06-1.8-1.8.06-.06A1.7 1.7 0 0 0 7.8 15a1.7 1.7 0 0 0-1.6-1.1H6v-2.6h.2A1.7 1.7 0 0 0 7.8 10a1.7 1.7 0 0 0-.34-1.88l-.06-.06 1.8-1.8.06.06A1.7 1.7 0 0 0 11.2 6a1.7 1.7 0 0 0 1.1-1.6V4h2.6v.08A1.7 1.7 0 0 0 16 5.7a1.7 1.7 0 0 0 1.94-.28l.06-.06 1.8 1.8-.06.06A1.7 1.7 0 0 0 19.4 9a1.7 1.7 0 0 0 1.6 1.1h.2v2.6H21a1.7 1.7 0 0 0-1.6 1.3z"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',plus:'<path d="M12 5v14M5 12h14"/>',logout:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',arrow:'<path d="m9 18 6-6-6-6"/>',file:'<path d="M4 4h16v16H4zM8 8h8M8 12h8M8 16h5"/>',send:'<path d="m22 2-7 20-4-9-9-4zM22 2 11 13"/>'};return `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${p[n]||p.home}</svg>`}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),2400)}
function current(){return state.users.find(u=>u.id===state.currentUser)}
function roleLabel(r){return ROLES[r]?.label||r}
function navItems(u){const common=[['dashboard','Dashboard','home']];if(['president','vice_president','secretary','membership'].includes(u.role))common.push(['members','Members','users']);if(['president','vice_president','secretary','project_director','member'].includes(u.role))common.push(['meetings','Meetings','calendar']);if(['president','vice_president','project_director','member'].includes(u.role))common.push(['projects','Projects','brief']);if(['president','project_director','member'].includes(u.role))common.push(['ideas','Ideas Hub','idea']);if(['president','treasurer'].includes(u.role))common.push(['finance','Finance','wallet']);if(['president','secretary','project_director','public_image','member'].includes(u.role))common.push(['documents','Documents','doc']);if(['president','project_director','member'].includes(u.role))common.push(['tasks','Tasks','check']);if(u.role==='president')common.push(['executives','Executives','users'],['plan','Presidential Plan','chart'],['notifications','Notifications','bell'],['reports','Reports','chart'],['handover','Handover','arrow'],['audit','Audit Log','doc']);if(['secretary'].includes(u.role))common.push(['notifications','Notifications','bell']);if(['project_director'].includes(u.role))common.push(['reports','Project Reports','chart']);if(['treasurer'].includes(u.role))common.push(['reports','Financial Reports','chart']);if(['public_image'].includes(u.role))common.push(['media','Media & Public Image','file']);common.push(['profile','My Profile','settings']);return common}
function layout(content){const u=current();const nav=navItems(u);return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">BR</div><div><div class="brand-title">BlueCrest Rotaract</div><div class="brand-sub">Club Management Hub</div></div></div><div class="nav-label">Workspace</div><nav class="nav">${nav.map(n=>`<button class="${page===n[0]?'active':''}" onclick="go('${n[0]}')">${icon(n[2])}<span>${n[1]}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="profile-mini"><div class="avatar">${initials(u.name)}</div><div><div class="name">${esc(u.name)}</div><div class="role">${roleLabel(u.role)}</div></div></div><button class="nav" style="width:100%;border:0;background:transparent" onclick="logout()"><span style="display:flex;align-items:center;gap:11px;padding:10px 12px;color:#68748b;font-size:13px">${icon('logout')} Log out</span></button></div></aside><main class="main"><header class="topbar"><button class="icon-btn mobile-menu" onclick="toggleMobile()">${icon('menu')}</button><div class="search">${icon('search')}<input id="globalSearch" placeholder="Search anything..." onkeydown="if(event.key==='Enter') doSearch(this.value)"></div><div class="top-actions"><button class="icon-btn" onclick="go('notifications')">${icon('bell')}<span style="font-size:9px;color:var(--red)">${state.notifications.filter(n=>!n.read).length||''}</span></button><button class="icon-btn" title="Log out" aria-label="Log out" onclick="logout()">${icon('logout')}</button><div class="user-chip"><div class="avatar">${initials(u.name)}</div><div><div class="user-name">${esc(u.name)}</div><div class="user-role">${roleLabel(u.role)}</div></div></div></div></header><div class="content">${content}</div><div class="mobile-nav">${nav.slice(0,5).map(n=>`<button class="${page===n[0]?'active':''}" onclick="go('${n[0]}')">${icon(n[2])}<span>${n[1]}</span></button>`).join('')}</div></main></div>`}
function dashboard(){const u=current();const isExec=u.role!=='member';const balance=state.transactions.reduce((a,t)=>a+(t.type==='Income'?t.amount:-t.amount),0);return `<div class="welcome"><div><div class="eyebrow">${isExec?'Executive workspace':'Member workspace'} • ${new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}</div><h1>Welcome back, ${esc(u.name.split(' ')[0])} 👋</h1><p>Here’s what’s happening across BlueCrest Rotaract Club.</p></div><button class="primary" onclick="quickAction()">${icon('plus')} Quick action</button></div><div class="stats"><div class="stat accent"><div class="stat-label">Active Members</div><div class="stat-value">${state.users.filter(x=>x.active).length}</div><div class="stat-note">Registered club accounts</div></div><div class="stat"><div class="stat-label">Active Projects</div><div class="stat-value">${state.projects.filter(x=>x.status!=='Completed').length}</div><div class="stat-note">Across service areas</div></div><div class="stat"><div class="stat-label">Upcoming Meetings</div><div class="stat-value">${state.meetings.length}</div><div class="stat-note">Scheduled sessions</div></div><div class="stat"><div class="stat-label">Club Ideas</div><div class="stat-value">${state.ideas.length}</div><div class="stat-note">${state.ideas.filter(i=>i.status==='Approved').length} approved</div></div></div><div class="grid"><div class="card span2"><div class="card-head"><h3>Club Projects</h3><button class="link" onclick="go('projects')">View all</button></div>${state.projects.slice(0,3).map(p=>`<div class="project-card"><div class="project-top"><div><div class="project-title">${esc(p.title)}</div><div class="project-meta">${esc(p.category)} • ${esc(p.date)}</div></div><span class="badge ${p.status==='Completed'?'green':p.status==='Planning'?'amber':'blue'}">${p.status}</span></div><div class="progress"><i style="width:${p.progress}%"></i></div><div class="project-foot"><span>Project progress</span><b>${p.progress}%</b></div></div>`).join('')}</div><div class="card"><div class="card-head"><h3>Upcoming Schedule</h3><button class="link" onclick="go('meetings')">Calendar</button></div><div class="list">${state.meetings.slice(0,3).map(m=>`<div class="list-row"><div class="item-left"><div class="item-icon">${icon('calendar')}</div><div><div class="item-title">${esc(m.title)}</div><div class="item-sub">${esc(m.date)} • ${esc(m.time)} • ${esc(m.location)}</div></div></div></div>`).join('')}</div></div><div class="card"><div class="card-head"><h3>Presidential Plan</h3><button class="link" onclick="go('plan')">Open</button></div><div style="display:flex;align-items:center;gap:18px"><div style="font-size:31px;font-weight:850;color:var(--navy)">${state.plan.progress}%</div><div style="flex:1"><div class="progress"><i style="width:${state.plan.progress}%"></i></div><div class="item-sub" style="margin-top:7px">${esc(state.plan.title)}</div></div></div><div class="list" style="margin-top:12px">${state.plan.items.slice(0,3).map(i=>`<div class="list-row"><div class="item-title">${esc(i.title)}</div><span class="badge ${i.status==='Completed'?'green':'blue'}">${i.progress}%</span></div>`).join('')}</div></div><div class="card"><div class="card-head"><h3>Latest Notifications</h3><button class="link" onclick="go('notifications')">View all</button></div>${state.notifications.slice(0,3).map(n=>`<div class="notice"><b>${esc(n.title)}</b><span>${esc(n.body)}</span></div>`).join('')}</div>${isExec&&u.role==='treasurer'?`<div class="card"><div class="card-head"><h3>Finance Snapshot</h3><button class="link" onclick="go('finance')">Open finance</button></div><div style="font-size:25px;font-weight:850">GHS ${balance.toLocaleString()}</div><div class="item-sub">Current recorded balance</div></div>`:''}<div class="card span3"><div class="card-head"><h3>Quick Access</h3></div><div class="quick-grid"><button class="quick" onclick="go('meetings')">${icon('calendar')}<b>Meetings</b><span>Schedule & attendance</span></button><button class="quick" onclick="go('projects')">${icon('brief')}<b>Projects</b><span>Track club projects</span></button><button class="quick" onclick="go('ideas')">${icon('idea')}<b>Idea Hub</b><span>Submit an idea</span></button><button class="quick" onclick="go('profile')">${icon('settings')}<b>My Profile</b><span>Account & security</span></button></div></div></div>`}
function pageHeader(title,sub,action=''){return `<div class="welcome"><div><div class="eyebrow">BlueCrest Rotaract Hub</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function members(){const canManage=['president','secretary','membership'].includes(current().role);return pageHeader('Members','Manage approved members and incoming registration applications.',canManage?`<button class="primary" onclick="openMemberModal()">${icon('plus')} Add member</button>`:'')+`<div class="stats"><div class="stat"><div class="stat-label">Active Members</div><div class="stat-value">${state.users.filter(u=>u.active).length}</div></div><div class="stat"><div class="stat-label">Pending Applications</div><div class="stat-value">${state.applications.filter(a=>a.status==='Pending').length}</div></div><div class="stat"><div class="stat-label">Tertiary</div><div class="stat-value">${state.users.filter(u=>u.education==='Tertiary').length}</div></div><div class="stat"><div class="stat-label">Executive Accounts</div><div class="stat-value">${state.users.filter(u=>u.role!=='member').length}</div></div></div><div class="grid"><div class="card span2"><div class="card-head"><h3>Registered Members</h3><button class="link" onclick="exportMembers()">Export CSV</button></div><div class="toolbar"><input placeholder="Search members..." oninput="filterMembers(this.value)"></div><div class="table-wrap"><table class="table"><thead><tr><th>Member</th><th>Education</th><th>Institution</th><th>Role</th><th>Status</th></tr></thead><tbody id="memberRows">${memberRows()}</tbody></table></div></div><div class="card"><div class="card-head"><h3>Registration Queue</h3></div>${state.applications.filter(a=>a.status==='Pending').map(a=>`<div class="list-row"><div class="item-left"><div class="avatar">${initials(a.name)}</div><div><div class="item-title">${esc(a.name)}</div><div class="item-sub">${esc(a.education)} • ${esc(a.institution)}</div></div></div>${canManage?`<button class="secondary" onclick="reviewApp('${a.id}')">Review</button>`:''}</div>`).join('')||'<div class="empty">No pending applications.</div>'}</div></div>`}
function memberRows(filter=''){const users=state.users.filter(u=>(u.name+' '+u.email).toLowerCase().includes(filter.toLowerCase()));return users.map(u=>`<tr><td><div class="person"><div class="avatar">${initials(u.name)}</div><div><b>${esc(u.name)}</b><div class="item-sub">${esc(u.email)}</div></div></div></td><td>${esc(u.education||'—')}</td><td>${esc(u.institution||'—')}</td><td><span class="badge blue">${roleLabel(u.role)}</span></td><td><span class="badge green">${u.active?'Active':'Suspended'}</span></td></tr>`).join('')}
function meetings(){const can=['president','secretary','vice_president','sergeant'].includes(current().role);return pageHeader('Meetings & Attendance','Arrange meetings, agendas, attendance and official minutes.',can?`<button class="primary" onclick="openMeetingModal()">${icon('plus')} New meeting</button>`:'')+`<div class="grid"><div class="card span2"><div class="card-head"><h3>Upcoming Meetings</h3></div>${state.meetings.map(m=>`<div class="project-card"><div class="project-top"><div><div class="project-title">${esc(m.title)}</div><div class="project-meta">${esc(m.date)} • ${esc(m.time)} • ${esc(m.location)} • ${esc(m.type)}</div></div><span class="badge blue">${m.status}</span></div><div style="display:flex;gap:8px;margin-top:10px">${can?`<button class="secondary" onclick="startMeeting('${m.id}')">${icon('check')} ${m.status==='Live'?'Meeting live':'Start meeting'}</button>`:''}<button class="secondary" onclick="attendance('${m.id}')">Attendance</button></div></div>`).join('')}</div><div class="card"><div class="card-head"><h3>Attendance Summary</h3></div><div style="font-size:35px;font-weight:850;color:var(--navy)">92%</div><div class="item-sub">Club attendance this month</div><div class="progress" style="margin-top:15px"><i style="width:92%"></i></div><div class="list" style="margin-top:10px"><div class="list-row"><span class="item-sub">Present</span><b>23</b></div><div class="list-row"><span class="item-sub">Apologies</span><b>2</b></div><div class="list-row"><span class="item-sub">Absent</span><b>1</b></div></div></div><div class="card span3"><div class="card-head"><h3>Meeting Records</h3><button class="link" onclick="openMinutesModal()">Add minutes</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Meeting</th><th>Date</th><th>Type</th><th>Status</th><th>Actions</th></tr></thead><tbody>${state.meetings.map(m=>`<tr><td>${esc(m.title)}</td><td>${esc(m.date)}</td><td>${esc(m.type)}</td><td><span class="badge ${m.status==='Live'?'green':'blue'}">${esc(m.status)}</span></td><td><button class="link" onclick="toast('Meeting record opened')">View minutes</button></td></tr>`).join('')}</tbody></table></div></div></div>`}
function projects(){const can=['president','project_director'].includes(current().role);return pageHeader('Projects','Plan outings, proposals, project teams, media and impact reports.',can?`<button class="primary" onclick="openProjectModal()">${icon('plus')} New project</button>`:'')+`<div class="stats"><div class="stat"><div class="stat-label">Total Projects</div><div class="stat-value">${state.projects.length}</div></div><div class="stat"><div class="stat-label">In Progress</div><div class="stat-value">${state.projects.filter(p=>p.status==='In Progress').length}</div></div><div class="stat"><div class="stat-label">Planning</div><div class="stat-value">${state.projects.filter(p=>p.status==='Planning').length}</div></div><div class="stat"><div class="stat-label">Completed</div><div class="stat-value">${state.projects.filter(p=>p.status==='Completed').length}</div></div></div><div class="grid">${state.projects.map(p=>`<div class="card"><div class="card-head"><span class="badge ${p.status==='Completed'?'green':p.status==='Planning'?'amber':'blue'}">${p.status}</span><span class="item-sub">${esc(p.date)}</span></div><h3 style="font-size:14px;margin:0 0 5px">${esc(p.title)}</h3><p class="item-sub">${esc(p.category)} • Lead: ${esc(p.lead)}</p><div class="progress" style="margin:16px 0 7px"><i style="width:${p.progress}%"></i></div><div class="project-foot"><span>Progress</span><b>${p.progress}%</b></div><div style="display:flex;gap:7px;margin-top:13px"><button class="secondary" onclick="projectDetail('${p.id}')">Open project</button>${can?`<button class="secondary" onclick="toast('Proposal workspace opened')">Proposal</button>`:''}</div></div>`).join('')}</div>`}
function ideas(){const canReview=['president','project_director'].includes(current().role);return pageHeader('Ideas Hub','A shared space for members to submit, review and develop club ideas.',`<button class="primary" onclick="openIdeaModal()">${icon('plus')} Submit idea</button>`)+`<div class="grid"><div class="card span2"><div class="card-head"><h3>Club Ideas</h3><button class="link" onclick="toast('Ideas sorted by community votes')">Sort by votes</button></div>${state.ideas.map(i=>`<div class="project-card"><div class="project-top"><div><div class="project-title">${esc(i.title)}</div><div class="project-meta">${esc(i.category)} • Submitted by ${esc(i.author)}</div></div><span class="badge ${i.status==='Approved'?'green':i.status==='Under Review'?'amber':'blue'}">${esc(i.status)}</span></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px"><span class="item-sub">${i.votes} community votes</span><div style="display:flex;gap:7px"><button class="secondary" onclick="voteIdea('${i.id}')">👍 Vote</button>${canReview?`<button class="secondary" onclick="reviewIdea('${i.id}')">Review</button>`:''}</div></div></div>`).join('')}</div><div class="card"><div class="card-head"><h3>Idea Categories</h3></div>${['Community Service','Professional Development','Environment','Membership','Technology','Social'].map((x,n)=>`<div class="list-row"><span class="item-title">${x}</span><span class="badge blue">${state.ideas.filter(i=>i.category===x).length}</span></div>`).join('')}</div></div>`}
function finance(){if(!['president','treasurer'].includes(current().role))return forbidden();const income=state.transactions.filter(t=>t.type==='Income').reduce((a,t)=>a+t.amount,0),expense=state.transactions.filter(t=>t.type==='Expense').reduce((a,t)=>a+t.amount,0);return pageHeader('Finance','Account records, transactions, project budgets and receipts.',`<button class="primary" onclick="openTransactionModal()">${icon('plus')} Record transaction</button>`)+`<div class="stats"><div class="stat accent"><div class="stat-label">Recorded Balance</div><div class="stat-value">GHS ${(income-expense).toLocaleString()}</div><div class="stat-note">Income less expenses</div></div><div class="stat"><div class="stat-label">Total Income</div><div class="stat-value">GHS ${income.toLocaleString()}</div></div><div class="stat"><div class="stat-label">Total Expenses</div><div class="stat-value">GHS ${expense.toLocaleString()}</div></div><div class="stat"><div class="stat-label">Transactions</div><div class="stat-value">${state.transactions.length}</div></div></div><div class="grid"><div class="card span2"><div class="card-head"><h3>Transactions</h3><button class="link" onclick="exportFinance()">Export CSV</button></div><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Date</th><th>Type</th><th>Description</th><th>Amount</th><th>Status</th></tr></thead><tbody>${state.transactions.map(t=>`<tr><td>${esc(t.id)}</td><td>${esc(t.date)}</td><td><span class="badge ${t.type==='Income'?'green':'red'}">${esc(t.type)}</span></td><td>${esc(t.description)}</td><td>GHS ${t.amount.toLocaleString()}</td><td><span class="badge green">${esc(t.status)}</span></td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="card-head"><h3>Budget by Project</h3></div>${state.projects.map(p=>`<div class="list-row"><div><div class="item-title">${esc(p.title)}</div><div class="item-sub">Project budget</div></div><b>GHS ${p.budget.toLocaleString()}</b></div>`).join('')}</div></div>`}
function documents(){return pageHeader('Documents','Access approved club, presidential, project and governance documents.',`<button class="primary" onclick="openDocModal()">${icon('plus')} Upload document</button>`)+`<div class="card"><div class="toolbar"><input placeholder="Search documents..." oninput="filterDocs(this.value)"><select><option>All categories</option><option>Presidential Plan</option><option>Governance</option><option>Minutes</option><option>Project</option></select></div><div class="table-wrap"><table class="table"><thead><tr><th>Document</th><th>Category</th><th>Date</th><th>Access</th><th></th></tr></thead><tbody id="docRows">${docRows()}</tbody></table></div></div>`}
function docRows(filter=''){return state.documents.filter(d=>d.name.toLowerCase().includes(filter.toLowerCase())).map(d=>`<tr><td><div class="person"><div class="item-icon">${icon('doc')}</div><div><b>${esc(d.name)}</b><div class="item-sub">Official club record</div></div></div></td><td>${esc(d.type)}</td><td>${esc(d.date)}</td><td><span class="badge green">Approved</span></td><td><button class="link" onclick="toast('Document preview opened')">View</button></td></tr>`).join('')}
function tasks(){return pageHeader('Tasks','Track responsibilities, deadlines and executive follow-ups.',`<button class="primary" onclick="openTaskModal()">${icon('plus')} New task</button>`)+`<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Task</th><th>Assigned to</th><th>Deadline</th><th>Status</th><th></th></tr></thead><tbody>${state.tasks.map(t=>`<tr><td><b>${esc(t.title)}</b></td><td>${esc(t.assignee)}</td><td>${esc(t.deadline)}</td><td><span class="badge ${t.status==='Completed'?'green':t.status==='Pending'?'amber':'blue'}">${esc(t.status)}</span></td><td><button class="link" onclick="cycleTask('${t.id}')">Update</button></td></tr>`).join('')}</tbody></table></div></div>`}
function plan(){const can=current().role==='president';return pageHeader('Presidential Plan of Action','Monitor the President’s strategic commitments and their progress.',can?`<button class="primary" onclick="updatePlan()">Update plan</button>`:'')+`<div class="grid"><div class="card span2"><div class="card-head"><h3>${esc(state.plan.title)}</h3><span class="badge blue">${state.plan.progress}% overall</span></div><div class="progress" style="height:10px"><i style="width:${state.plan.progress}%"></i></div><div class="list" style="margin-top:14px">${state.plan.items.map((i,n)=>`<div class="list-row"><div style="flex:1"><div class="item-title">${esc(i.title)}</div><div class="progress" style="margin-top:8px"><i style="width:${i.progress}%"></i></div></div><span class="badge ${i.status==='Completed'?'green':'blue'}">${i.progress}%</span></div>`).join('')}</div></div><div class="card"><div class="card-head"><h3>Plan Health</h3></div><div style="font-size:35px;font-weight:850;color:var(--navy)">${state.plan.progress}%</div><p class="item-sub">Current completion across strategic objectives.</p><button class="secondary" onclick="go('reports')">View report</button></div></div>`}
function notifications(){return pageHeader('Notifications','Official messages, reminders and updates for your club account.',current().role==='president'?`<button class="primary" onclick="openNotificationModal()">${icon('send')} Send notification</button>`:'')+`<div class="card">${state.notifications.map(n=>`<div class="notice" style="background:${n.read?'#fff':'#f5f7ff'}"><div style="display:flex;justify-content:space-between;gap:10px"><div><b>${esc(n.title)}</b><span>${esc(n.body)}</span></div><span class="item-sub">${esc(n.date)}</span></div>${!n.read?`<button class="link" style="padding:7px 0" onclick="readNotice('${n.id}')">Mark as read</button>`:''}</div>`).join('')}</div>`}
function executives(){if(current().role!=='president')return forbidden();return pageHeader('Executives','Appoint, manage and define responsibilities for club leadership positions.',`<button class="primary" onclick="openExecModal()">${icon('plus')} Add position / appoint</button>`)+`<div class="grid">${state.executives.map((e,i)=>`<div class="card"><div class="card-head"><span class="badge blue">Executive</span><button class="link" onclick="toast('Position management opened')">Manage</button></div><h3 style="font-size:14px;margin:0 0 5px">${esc(e.position)}</h3><div class="person" style="margin:12px 0"><div class="avatar">${initials(e.holder)}</div><div><b style="font-size:11px">${esc(e.holder)}</b><div class="item-sub">Since ${esc(e.start)}</div></div></div><p class="item-sub">Position responsibilities can be configured when this position is created or appointed.</p></div>`).join('')}</div>`}
function reports(){const r=current().role; if(!['president','project_director','treasurer'].includes(r))return forbidden();return pageHeader(r==='treasurer'?'Financial Reports':r==='project_director'?'Project Reports':'Club Reports','Generate management summaries for club records and accountability.',`<button class="primary" onclick="toast('Report generated for download')">Generate report</button>`)+`<div class="grid"><div class="card"><div class="card-head"><h3>Membership</h3></div><div style="font-size:30px;font-weight:850">${state.users.length}</div><p class="item-sub">Total user accounts</p></div><div class="card"><div class="card-head"><h3>Projects</h3></div><div style="font-size:30px;font-weight:850">${state.projects.length}</div><p class="item-sub">${state.projects.filter(p=>p.status==='Completed').length} completed</p></div><div class="card"><div class="card-head"><h3>Plan progress</h3></div><div style="font-size:30px;font-weight:850">${state.plan.progress}%</div><p class="item-sub">Presidential plan completion</p></div><div class="card span3"><div class="card-head"><h3>Monthly activity</h3></div><div class="chart">${[45,70,55,88,62,80,72,95,65,78,84,92].map((v,i)=>`<div class="bar" style="height:${v}%"><span>${i+1}</span></div>`).join('')}</div></div></div>`}
function handover(){if(current().role!=='president')return forbidden();return pageHeader('Presidential Handover','Transfer presidential responsibility through a controlled handover checklist.',`<button class="primary" onclick="openHandoverModal()">Start handover</button>`)+`<div class="grid"><div class="card span2"><div class="card-head"><h3>Handover checklist</h3><span class="badge amber">Ready for preparation</span></div>${['Presidential Plan of Action','Club documents','Active projects','Financial records','Executive appointments','Member records','Meeting records','Pending tasks & commitments'].map((x,i)=>`<div class="list-row"><div class="item-left"><div class="item-icon">${icon('check')}</div><div class="item-title">${x}</div></div><span class="badge ${i<3?'green':'blue'}">${i<3?'Ready':'Review'}</span></div>`).join('')}</div><div class="card"><div class="card-head"><h3>Process</h3></div><div class="item-sub" style="line-height:1.8">1. Select incoming President<br>2. Review checklist<br>3. Incoming President accepts<br>4. System records the handover<br>5. New role becomes active</div></div></div>`}
function audit(){if(current().role!=='president')return forbidden();return pageHeader('Audit Log','Immutable-style activity history for important club actions.')+`<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>User</th><th>Action</th></tr></thead><tbody>${state.audit.slice().reverse().map(a=>`<tr><td>${esc(a.date)}</td><td>${esc(a.user)}</td><td>${esc(a.action)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">No activity recorded yet.</td></tr>'}</tbody></table></div></div>`}
function profile(){const u=current();return pageHeader('My Profile','Manage your account information and security settings.')+`<div class="profile-banner"><div class="avatar">${initials(u.name)}</div><div><h2>${esc(u.name)}</h2><p>${roleLabel(u.role)} • ${esc(u.email)}</p></div></div><div class="grid"><div class="card span2"><div class="card-head"><h3>Account Information</h3><button class="link" onclick="openProfileModal()">Edit allowed fields</button></div><div class="form-grid"><div class="field"><label>Full name</label><input value="${esc(u.name)}" disabled></div><div class="field"><label>Role</label><input value="${esc(roleLabel(u.role))}" disabled></div><div class="field"><label>Email</label><input value="${esc(u.email)}" disabled></div><div class="field"><label>Education</label><input value="${esc(u.education||'Not specified')}" disabled></div><div class="field full"><label>Institution / Background</label><input value="${esc(u.institution||'Not specified')}" disabled></div></div></div><div class="card"><div class="card-head"><h3>Security</h3></div><div class="notice"><b>Password</b><span>Change your password at any time.</span></div><button class="primary" style="width:100%" onclick="openPasswordModal()">${icon('lock')} Change password</button></div></div>`}
function media(){return pageHeader('Media & Public Image','Manage approved club publicity, event media and communications.',`<button class="primary" onclick="toast('Media upload workspace opened')">${icon('plus')} Add media</button>`)+`<div class="grid">${['Community Clean-Up','Digital Safety Workshop','Club Fellowship','District Activity'].map((x,i)=>`<div class="card"><div style="height:120px;background:linear-gradient(135deg,#edf2ff,#f8faff);border-radius:9px;display:grid;place-items:center;color:var(--navy)">${icon('file')}</div><h3 style="font-size:12px;margin:12px 0 4px">${x}</h3><p class="item-sub">Approved club media • ${i+2} items</p></div>`).join('')}</div>`}
function forbidden(){return `<div class="card" style="max-width:600px;margin:30px auto;text-align:center"><div style="font-size:36px">🔒</div><h2 style="font-size:18px">Access restricted</h2><p class="item-sub">Your current role does not have permission to access this workspace.</p><button class="primary" onclick="go('dashboard')">Return to dashboard</button></div>`}
function doSearch(q){if(!q.trim())return;toast(`Search: ${q}`);}
function render(){const app=document.getElementById('app');if(!state.currentUser){app.innerHTML=loginPage();return}let c={dashboard,members,meetings,projects,ideas,finance,documents,tasks,plan,notifications,executives,reports,handover,audit,profile,media}[page]||dashboard;app.innerHTML=layout(c());if(current().mustChange)openPasswordModal(true)}
function loginPage(){return `<div class="login-page"><section class="login-visual"><div class="login-brand"><div class="brand-mark">BR</div><div>BlueCrest Rotaract<br><small style="opacity:.65;font-weight:500">Club Management Hub</small></div></div><div><h1>One club.<br>One connected hub.</h1><p>Manage members, meetings, projects, ideas, documents, finances and presidential plans from one clean workspace built for BlueCrest Rotaract.</p><div class="login-points"><div class="login-point">👥 Member management</div><div class="login-point">🚀 Project lifecycle</div><div class="login-point">📅 Meetings & attendance</div><div class="login-point">💰 Financial records</div></div></div><div style="font-size:10px;opacity:.55">BlueCrest Rotaract Club • 2026–2027</div></section><section class="auth-wrap"><div class="auth"><div class="eyebrow">Member & Executive Portal</div><h2>Sign in</h2><div class="auth-sub">Use the account assigned to your Rotaract role.</div><form onsubmit="login(event)"><div class="field"><label>Email address</label><input id="loginEmail" type="email" placeholder="you@example.com" required></div><div class="field"><label>Password</label><input id="loginPassword" type="password" placeholder="Your password" required></div><button class="primary" type="submit">Sign in ${icon('arrow')}</button></form><div class="demo-box"><strong>Demo access</strong><br>President: president@bluecrestrotaract.org<br>Secretary: secretary@bluecrestrotaract.org<br>Project Director: projects@bluecrestrotaract.org<br>Treasurer: treasurer@bluecrestrotaract.org<br>Password for each demo account is shown in the project README.</div><div style="text-align:center;margin-top:18px"><button class="link" onclick="openRegisterModal()">New member? Register here</button></div></div></section></div>`}
function login(e){e.preventDefault();const email=document.getElementById('loginEmail').value.trim().toLowerCase(),pw=document.getElementById('loginPassword').value;const u=state.users.find(x=>x.email.toLowerCase()===email&&x.password===pw&&x.active);if(!u)return toast('Invalid email or password.');state.currentUser=u.id;page='dashboard';auditLog(`Signed in as ${roleLabel(u.role)}`);save();render()}
function logout(){state.currentUser=null;save();page='dashboard';render();toast('Signed out')}
function go(p){page=p;render()}
function auditLog(action){const u=current();state.audit.push({date:new Date().toLocaleString('en-GB'),user:u?.name||'System',action})}
function toggleMobile(){document.querySelector('.sidebar')?.classList.toggle('mobile-open')}
function quickAction(){const u=current();if(u.role==='president')openNotificationModal();else if(u.role==='project_director')openProjectModal();else if(u.role==='treasurer')openTransactionModal();else if(u.role==='secretary')openMeetingModal();else openIdeaModal()}
function modal(title,body,actions=''){const x=document.createElement('div');x.className='modal-backdrop';x.id='modal';x.innerHTML=`<div class="modal"><h2>${title}</h2><p>${body}</p><div id="modalBody"></div>${actions?`<div class="modal-actions">${actions}</div>`:''}</div>`;document.body.appendChild(x);return x}
function closeModal(){document.getElementById('modal')?.remove()}
function openPasswordModal(force=false){const u=current();const x=modal(force?'Set a new password':'Change password',force?'For security, you must change the password assigned to your account before continuing.':'Enter your current password and choose a new password.');document.getElementById('modalBody').innerHTML=`<div class="form-grid"><div class="field full"><label>Current password</label><input id="oldPw" type="password" ${force?'value="'+esc(u.password)+'" readonly':''}></div><div class="field"><label>New password</label><input id="newPw" type="password" minlength="8"></div><div class="field"><label>Confirm new password</label><input id="newPw2" type="password" minlength="8"></div></div><div class="notice" style="margin-top:14px"><b>Password rule</b><span>Use at least 8 characters. Avoid sharing passwords with other members.</span></div>`;document.querySelector('#modal .modal-actions')?.remove();x.querySelector('.modal').insertAdjacentHTML('beforeend',`<div class="modal-actions">${force?'':'<button class="secondary" onclick="closeModal()">Cancel</button>'}<button class="primary" onclick="changePassword(${force})">Save new password</button></div>`)}
function changePassword(force){const u=current(),old=document.getElementById('oldPw').value,n=document.getElementById('newPw').value,n2=document.getElementById('newPw2').value;if(!force&&old!==u.password)return toast('Current password is incorrect.');if(n.length<8)return toast('New password must be at least 8 characters.');if(n!==n2)return toast('Passwords do not match.');u.password=n;u.mustChange=false;auditLog('Changed account password');save();closeModal();render();toast('Password changed successfully')}
function openRegisterModal(){const x=modal('Member registration','Submit your basic information and educational background. Your application will remain pending until reviewed by the club.');document.getElementById('modalBody').innerHTML=`<div class="form-grid"><div class="field"><label>Full name *</label><input id="rName" required></div><div class="field"><label>Email *</label><input id="rEmail" type="email"></div><div class="field"><label>Phone</label><input id="rPhone"></div><div class="field"><label>Education level *</label><select id="rEdu"><option>Primary</option><option>Junior High School</option><option>Senior High School</option><option selected>Tertiary</option><option>Graduate</option><option>Postgraduate</option><option>Other</option><option>None</option></select></div><div class="field"><label>Institution / background *</label><input id="rInst"></div><div class="field"><label>Program / course</label><input id="rProgram"></div><div class="field"><label>Level</label><input id="rLevel" placeholder="e.g. Level 100"></div><div class="field full"><label>Why would you like to join Rotaract?</label><textarea id="rReason" rows="3"></textarea></div></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="submitRegistration()">Submit registration</button></div>`}
function submitRegistration(){const a={id:'a'+Date.now(),name:document.getElementById('rName').value.trim(),email:document.getElementById('rEmail').value.trim(),phone:document.getElementById('rPhone').value.trim(),education:document.getElementById('rEdu').value,institution:document.getElementById('rInst').value.trim(),program:document.getElementById('rProgram').value.trim(),level:document.getElementById('rLevel').value.trim(),status:'Pending',date:new Date().toLocaleDateString('en-GB')};if(!a.name||!a.email||!a.institution)return toast('Please complete the required fields.');state.applications.push(a);save();closeModal();toast('Registration submitted for review.')}
function openMemberModal(){const x=modal('Add new member','Create an approved member account. A temporary password will be generated and the member must change it on first login.');document.getElementById('modalBody').innerHTML=`<div class="form-grid"><div class="field"><label>Full name</label><input id="mName"></div><div class="field"><label>Email</label><input id="mEmail" type="email"></div><div class="field"><label>Education</label><select id="mEdu"><option>Tertiary</option><option>Senior High School</option><option>Junior High School</option><option>Graduate</option><option>Other</option><option>None</option></select></div><div class="field"><label>Institution / background</label><input id="mInst"></div></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="addMember()">Create account</button></div>`}
function addMember(){const name=document.getElementById('mName').value.trim(),email=document.getElementById('mEmail').value.trim();if(!name||!email)return toast('Name and email are required.');if(state.users.some(u=>u.email===email))return toast('Email already exists.');const temp='BCR-'+Math.random().toString(36).slice(2,8).toUpperCase();state.users.push({id:'u'+Date.now(),name,email,role:'member',password:temp,mustChange:true,active:true,education:document.getElementById('mEdu').value,institution:document.getElementById('mInst').value.trim()});auditLog(`Added member account for ${name}`);save();closeModal();toast(`Member added. Temporary password: ${temp}`);go('members')}
function reviewApp(id){const a=state.applications.find(x=>x.id===id);const x=modal('Review member application',`${a.name} • ${a.email}`);document.getElementById('modalBody').innerHTML=`<div class="notice"><b>Education</b><span>${esc(a.education)} • ${esc(a.institution)} ${a.program?'• '+esc(a.program):''} ${a.level?'• '+esc(a.level):''}</span></div><div class="modal-actions"><button class="danger" onclick="rejectApp('${id}')">Reject</button><button class="primary" onclick="acceptApp('${id}')">Accept & create account</button></div>`}
function acceptApp(id){const a=state.applications.find(x=>x.id===id);const temp='BCR-'+Math.random().toString(36).slice(2,8).toUpperCase();state.users.push({id:'u'+Date.now(),name:a.name,email:a.email,role:'member',password:temp,mustChange:true,active:true,education:a.education,institution:a.institution});a.status='Accepted';auditLog(`Accepted membership application for ${a.name}`);save();closeModal();toast(`Accepted. Temporary password: ${temp}`);go('members')}
function rejectApp(id){const a=state.applications.find(x=>x.id===id);a.status='Rejected';auditLog(`Rejected membership application for ${a.name}`);save();closeModal();toast('Application rejected')}
function openMeetingModal(){const x=modal('Schedule meeting','Create a club, executive or project meeting.');document.getElementById('modalBody').innerHTML=`<div class="form-grid"><div class="field full"><label>Meeting title</label><input id="mtTitle"></div><div class="field"><label>Date</label><input id="mtDate" type="date"></div><div class="field"><label>Time</label><input id="mtTime" type="time"></div><div class="field"><label>Location</label><input id="mtLoc" placeholder="SRC Hall / Google Meet"></div><div class="field"><label>Type</label><select id="mtType"><option>Physical</option><option>Virtual</option><option>Hybrid</option></select></div></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="addMeeting()">Schedule</button></div>`}
function addMeeting(){const t=document.getElementById('mtTitle').value.trim();if(!t)return toast('Meeting title is required.');state.meetings.push({id:'m'+Date.now(),title:t,date:document.getElementById('mtDate').value||'TBD',time:document.getElementById('mtTime').value||'TBD',location:document.getElementById('mtLoc').value||'TBD',type:document.getElementById('mtType').value,status:'Scheduled'});auditLog(`Scheduled meeting: ${t}`);save();closeModal();render();toast('Meeting scheduled')}
function startMeeting(id){const m=state.meetings.find(x=>x.id===id);m.status='Live';auditLog(`Started meeting: ${m.title}`);save();render();toast('Meeting started — attendance is now open')}
function attendance(id){const m=state.meetings.find(x=>x.id===id);const x=modal('Attendance',`${m.title} • ${m.date} • ${m.time}`);document.getElementById('modalBody').innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>Member</th><th>Status</th></tr></thead><tbody>${state.users.filter(u=>u.active).map(u=>`<tr><td>${esc(u.name)}</td><td><select onchange="setAttendance('${id}','${u.id}',this.value)"><option>Present</option><option>Late</option><option>Excused</option><option>Absent</option></select></td></tr>`).join('')}</tbody></table></div><div class="modal-actions"><button class="primary" onclick="closeModal()">Save attendance</button></div>`}
function setAttendance(meeting,member,status){const old=state.attendance.find(a=>a.meeting===meeting&&a.member===member);if(old)old.status=status;else state.attendance.push({meeting,member,status});save()}
function openMinutesModal(){const x=modal('Record meeting minutes','Capture discussions, decisions and action items.');document.getElementById('modalBody').innerHTML=`<div class="form-grid"><div class="field"><label>Meeting</label><select>${state.meetings.map(m=>`<option>${esc(m.title)}</option>`).join('')}</select></div><div class="field"><label>Chairperson</label><input value="${esc(current().name)}"></div><div class="field full"><label>Discussions</label><textarea rows="4"></textarea></div><div class="field full"><label>Decisions / action items</label><textarea rows="4"></textarea></div></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="closeModal();toast('Meeting minutes saved')">Save minutes</button></div>`}
function openProjectModal(){const x=modal('Create project','Start a project workspace with a category, date and initial budget.');document.getElementById('modalBody').innerHTML=`<div class="form-grid"><div class="field full"><label>Project title</label><input id="pTitle"></div><div class="field"><label>Category</label><select id="pCat"><option>Community Service</option><option>Professional Development</option><option>Environment</option><option>Membership</option><option>Technology</option><option>Social</option></select></div><div class="field"><label>Target date</label><input id="pDate" type="date"></div><div class="field"><label>Lead</label><input id="pLead" value="${esc(roleLabel(current().role))}"></div><div class="field"><label>Budget (GHS)</label><input id="pBudget" type="number" min="0"></div><div class="field full"><label>Objectives / description</label><textarea id="pDesc" rows="4"></textarea></div></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="addProject()">Create project</button></div>`}
function addProject(){const title=document.getElementById('pTitle').value.trim();if(!title)return toast('Project title is required.');state.projects.push({id:'p'+Date.now(),title,category:document.getElementById('pCat').value,lead:document.getElementById('pLead').value,date:document.getElementById('pDate').value||'TBD',budget:Number(document.getElementById('pBudget').value)||0,progress:0,status:'Planning'});auditLog(`Created project: ${title}`);save();closeModal();render();toast('Project created')}
function projectDetail(id){const p=state.projects.find(x=>x.id===id);const x=modal(p.title,`${p.category} • Target ${p.date}`);document.getElementById('modalBody').innerHTML=`<div class="notice"><b>Project progress</b><span>${p.progress}% • ${p.status}</span><div class="progress" style="margin-top:9px"><i style="width:${p.progress}%"></i></div></div><div class="form-grid"><div class="field"><label>Lead</label><input value="${esc(p.lead)}" disabled></div><div class="field"><label>Budget</label><input value="GHS ${p.budget.toLocaleString()}" disabled></div><div class="field full"><label>Next project action</label><input id="nextAction" placeholder="e.g. Finalize proposal and confirm venue"></div></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Close</button><button class="primary" onclick="toast('Project action recorded');closeModal()">Save update</button></div>`}
function openIdeaModal(){const x=modal('Submit a club idea','Ideas are visible to authorized reviewers and can be converted into project proposals.');document.getElementById('modalBody').innerHTML=`<div class="form-grid"><div class="field full"><label>Idea title</label><input id="iTitle"></div><div class="field"><label>Category</label><select id="iCat"><option>Community Service</option><option>Professional Development</option><option>Environment</option><option>Membership</option><option>Technology</option><option>Social</option></select></div><div class="field"><label>Target beneficiaries</label><input id="iTarget"></div><div class="field full"><label>Problem / proposed solution</label><textarea id="iDesc" rows="4"></textarea></div></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="addIdea()">Submit idea</button></div>`}
function addIdea(){const title=document.getElementById('iTitle').value.trim();if(!title)return toast('Idea title is required.');state.ideas.unshift({id:'i'+Date.now(),title,author:current().name,category:document.getElementById('iCat').value,status:'Under Review',votes:0});auditLog(`Submitted club idea: ${title}`);save();closeModal();render();toast('Idea submitted')}
function voteIdea(id){const i=state.ideas.find(x=>x.id===id);i.votes++;save();render();toast('Vote recorded')}
function reviewIdea(id){const i=state.ideas.find(x=>x.id===id);i.status=i.status==='Approved'?'Under Review':'Approved';auditLog(`Updated idea status: ${i.title} → ${i.status}`);save();render();toast(`Idea marked ${i.status}`)}
function openTransactionModal(){const x=modal('Record transaction','Record income, expense or transfer. Attach receipts when the production database is connected.');document.getElementById('modalBody').innerHTML=`<div class="form-grid"><div class="field"><label>Type</label><select id="txType"><option>Income</option><option>Expense</option><option>Transfer</option></select></div><div class="field"><label>Amount (GHS)</label><input id="txAmount" type="number" min="0"></div><div class="field"><label>Category</label><input id="txCat" placeholder="Membership Dues / Project"></div><div class="field"><label>Date</label><input id="txDate" type="date"></div><div class="field full"><label>Description</label><input id="txDesc"></div></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="addTransaction()">Save transaction</button></div>`}
function addTransaction(){const amount=Number(document.getElementById('txAmount').value);if(!amount)return toast('Enter a valid amount.');state.transactions.push({id:'TX-'+String(state.transactions.length+1).padStart(3,'0'),date:document.getElementById('txDate').value||new Date().toLocaleDateString('en-GB'),type:document.getElementById('txType').value,category:document.getElementById('txCat').value||'General',description:document.getElementById('txDesc').value||'Transaction',amount,status:'Pending Approval'});auditLog(`Recorded ${document.getElementById('txType').value} transaction of GHS ${amount}`);save();closeModal();render();toast('Transaction recorded')}
function openNotificationModal(){const x=modal('Send club notification','Send an official message to all registered members.');document.getElementById('modalBody').innerHTML=`<div class="form-grid"><div class="field full"><label>Title</label><input id="nTitle"></div><div class="field full"><label>Message</label><textarea id="nBody" rows="5"></textarea></div></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="sendNotification()">Send notification</button></div>`}
function sendNotification(){const title=document.getElementById('nTitle').value.trim(),body=document.getElementById('nBody').value.trim();if(!title||!body)return toast('Title and message are required.');state.notifications.unshift({id:'n'+Date.now(),title,body,date:new Date().toLocaleDateString('en-GB'),read:false});auditLog(`Sent club notification: ${title}`);save();closeModal();render();toast('Notification sent')}
function readNotice(id){const n=state.notifications.find(x=>x.id===id);n.read=true;save();render()}
function openDocModal(){const x=modal('Upload document','Choose a document category and record the file. Storage is simulated in this browser build.');document.getElementById('modalBody').innerHTML=`<div class="form-grid"><div class="field full"><label>Document name</label><input id="docName"></div><div class="field"><label>Category</label><select id="docType"><option>Presidential Plan</option><option>Governance</option><option>Minutes</option><option>Project</option><option>Financial</option><option>Other</option></select></div><div class="field"><label>File</label><input id="docFile" type="file"></div></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="addDoc()">Save document</button></div>`}
function addDoc(){const name=document.getElementById('docName').value.trim();if(!name)return toast('Document name is required.');state.documents.unshift({id:'d'+Date.now(),name,type:document.getElementById('docType').value,date:new Date().toLocaleDateString('en-GB')});auditLog(`Added document: ${name}`);save();closeModal();render();toast('Document record added')}
function openTaskModal(){const x=modal('Create task','Assign a responsibility and deadline.');document.getElementById('modalBody').innerHTML=`<div class="form-grid"><div class="field full"><label>Task</label><input id="taskTitle"></div><div class="field"><label>Assigned role / person</label><input id="taskAssignee"></div><div class="field"><label>Deadline</label><input id="taskDeadline" type="date"></div></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="addTask()">Create task</button></div>`}
function addTask(){const title=document.getElementById('taskTitle').value.trim();if(!title)return toast('Task is required.');state.tasks.unshift({id:'t'+Date.now(),title,assignee:document.getElementById('taskAssignee').value||roleLabel(current().role),deadline:document.getElementById('taskDeadline').value||'TBD',status:'Pending'});auditLog(`Created task: ${title}`);save();closeModal();render();toast('Task created')}
function cycleTask(id){const t=state.tasks.find(x=>x.id===id);t.status=t.status==='Pending'?'In Progress':t.status==='In Progress'?'Completed':'Pending';save();render();toast(`Task: ${t.status}`)}
function updatePlan(){const p=state.plan;p.progress=Math.min(100,p.progress+5);p.items[0].progress=Math.min(100,p.items[0].progress+5);auditLog('Updated presidential plan progress');save();render();toast('Presidential plan updated')}
function openExecModal(){const x=modal('Create / appoint executive position','The President can create a position and assign a current member.');document.getElementById('modalBody').innerHTML=`<div class="form-grid"><div class="field"><label>Position name</label><input id="ePos"></div><div class="field"><label>Start date</label><input id="eDate" type="date"></div><div class="field full"><label>Assign to member</label><select id="eHolder">${state.users.filter(u=>u.active).map(u=>`<option value="${esc(u.name)}">${esc(u.name)}</option>`).join('')}</select></div><div class="field full"><label>Responsibilities</label><textarea id="eResp" rows="4" placeholder="Describe the responsibilities and permissions of this position."></textarea></div></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="addExec()">Create appointment</button></div>`}
function addExec(){const pos=document.getElementById('ePos').value.trim();if(!pos)return toast('Position name is required.');state.executives.push({position:pos,holder:document.getElementById('eHolder').value,start:document.getElementById('eDate').value||new Date().toLocaleDateString('en-GB')});auditLog(`Created executive position and appointment: ${pos}`);save();closeModal();render();toast('Executive position created')}
function openHandoverModal(){const presidents=state.users.filter(u=>u.active&&u.id!==current().id);const x=modal('Presidential handover','This action should be used only after the club has reviewed the handover checklist.');document.getElementById('modalBody').innerHTML=`<div class="field"><label>Incoming President</label><select id="incoming">${presidents.map(u=>`<option value="${u.id}">${esc(u.name)} — ${esc(roleLabel(u.role))}</option>`).join('')}</select></div><div class="notice" style="margin-top:14px"><b>Confirmation</b><span>The system will create a handover record. A production version should require acceptance by the incoming President before role activation.</span></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="confirmHandover()">Start handover</button></div>`}
function confirmHandover(){const id=document.getElementById('incoming').value,u=state.users.find(x=>x.id===id);auditLog(`Started presidential handover to ${u.name}`);state.notifications.unshift({id:'n'+Date.now(),title:'Presidential handover initiated',body:`A presidential handover has been initiated to ${u.name}.`,date:new Date().toLocaleDateString('en-GB'),read:false});save();closeModal();toast('Handover initiated')}
function openProfileModal(){const u=current();const x=modal('Update profile','Role and email are controlled by the club. Only permitted personal fields can be edited.');document.getElementById('modalBody').innerHTML=`<div class="form-grid"><div class="field"><label>Full name</label><input id="pfName" value="${esc(u.name)}"></div><div class="field"><label>Phone</label><input id="pfPhone" value="${esc(u.phone||'')}"></div><div class="field"><label>Education</label><input value="${esc(u.education||'')}" disabled></div><div class="field"><label>Institution</label><input value="${esc(u.institution||'')}" disabled></div></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="saveProfile()">Save changes</button></div>`}
function saveProfile(){const u=current();u.name=document.getElementById('pfName').value.trim()||u.name;u.phone=document.getElementById('pfPhone').value.trim();auditLog('Updated profile information');save();closeModal();render();toast('Profile updated')}
function filterMembers(q){document.getElementById('memberRows').innerHTML=memberRows(q)}
function filterDocs(q){document.getElementById('docRows').innerHTML=docRows(q)}
function exportMembers(){downloadCSV('members.csv',state.users.map(u=>({Name:u.name,Email:u.email,Role:roleLabel(u.role),Education:u.education,Institution:u.institution,Status:u.active?'Active':'Suspended'})))}
function exportFinance(){downloadCSV('finance.csv',state.transactions)}
function downloadCSV(name,rows){if(!rows.length)return;const keys=Object.keys(rows[0]);const csv=[keys.join(','),...rows.map(r=>keys.map(k=>`"${String(r[k]??'').replace(/"/g,'""')}"`).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
render();
